  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Mecamylamine, a small lipophilic bicyclic amine, has complete oral bioavailability in healthy subjects; this is the closest pharmacophore analogue to the adamantane primary amine query and supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Lamotrigine, a small lipophilic drug containing amino groups, has 98% absolute oral bioavailability in humans, demonstrating that small amino-containing lipophilic molecules can be essentially completely absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Levomilnacipran, a small primary-amine-containing drug, has >90% oral bioavailability in humans, supporting high F for small polar amines.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Saxagliptin, a small aminoamide drug, has 50–67% oral bioavailability in healthy volunteers, well above the 20% threshold and supportive of high F for small amine-containing drugs.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small lipophilic adamantane primary amine (memantine). The most relevant analogue, mecamylamine, shows complete oral bioavailability, and other small amine-containing drugs show high F; low-F retrieved compounds are charged carboxylic acids/zwitterions and are not transferable. Thus predict high (F >= 20%).",
  "evidence_gaps": [
    "No direct memantine bioavailability record is present in the evidence set; nearest analogues have low Morgan similarity (<0.25).",
    "Absolute human F for the exact query was not experimentally reported among the retrieved records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

